+
+export function PredictionChart({result,mode,feature,showTraining}:{result:BenchResult;mode:"parity"|"residual"|"feature";feature:number;showTraining:boolean}){
+  const {ref,width}=useWidth();const height=width<500?285:340;const left=55,right=20,top=20,bottom=48;
