+"use client";
+import { useEffect, useState } from "react";
+import { Flag, Check, RotateCcw, Copy } from "lucide-react";
+import { conceptDefaults, conceptKey, conceptNumber, type ConceptInput, type ConceptResult } from "@/lib/concepts";
