+
+const titles={error:"驶入最小误差港",sensitivity:"一枚路钉，两种回应",regularization:"收起枝条，再看远处"};
+export default function ConceptQuest({input,result,pending,onInput}:{input:ConceptInput;result:ConceptResult;pending:boolean;onInput:(p:ConceptInput)=>void}) {
+  const [origin,setOrigin]=useState<ConceptInput|null>(null),[target,setTarget]=useState("");
+  const [baseline,setBaseline]=useState<ConceptResult|null>(null),[answer,setAnswer]=useState("");
+  const [checked,setChecked]=useState<{key:string;answer:string}|null>(null),[copied,setCopied]=useState(false);
+  const key=conceptKey(input), matched=!pending&&conceptKey(result.parameters)===key;
+  useEffect(()=>{if(target && matched && conceptKey(result.parameters)===target){setBaseline(result);setTarget("");}},[target,matched,result]);
+  const observation=baseline?observeQuest(baseline,result):null;
+  const currentCheck=checked?.key===key&&matched?checked:null;
+  const correct=!!currentCheck&&currentCheck.answer===observation?.correct;
+  function start(){
+    if(!origin)setOrigin(structuredClone(input));
+    const next={...conceptDefaults,panel:input.panel,slope:1.8,intercept:.8,alpha:input.panel==="sensitivity"?1e-6:1e-8};
+    setBaseline(null);setAnswer("");setChecked(null);setCopied(false);setTarget(conceptKey(next));onInput(next);
+  }
+  async function copy(){
+    if(!correct||!observation)return;
+    try{await navigator.clipboard.writeText(JSON.stringify({kind:"island-discovery",created_at:new Date().toISOString(),parameters:input,baseline_parameters:baseline!.parameters,data_fingerprint:result.data_fingerprint,validation_fingerprint:result.validation_fingerprint,choice:currentCheck!.answer,evidence:observation.evidence,formal_grade:false},null,2));setCopied(true);}catch{setCopied(false);}
+  }
+  return <section className="island-quest" aria-label="岛屿观察任务">
+    <div className="island-quest-heading"><Flag size={17}/><h3>{titles[input.panel]}</h3><span>探索任务</span></div>
+    {!baseline&&!target?<><p>布置一组固定条件，操作物件，再用实际数值回答。可随时返回原实验。</p><button className="button primary" disabled={!matched} onClick={start}>布置观察任务</button></>:target?<p role="status">正在实算任务起点…</p>:observation&&<>
+      <p>{observation.ready?"操作条件已满足，看看这次实际发生了什么。":observation.reason}</p>
+      {observation.progress!==undefined&&<label className="quest-progress">可减少训练误差已消除 <output>{Math.round(observation.progress*100)}%</output><progress max="1" value={observation.progress}/></label>}
