+    ctx.beginPath();ctx.moveTo(x(point.x)-9,y(point.y));ctx.lineTo(x(point.x)+9,y(point.y));ctx.moveTo(x(point.x),y(point.y)-9);ctx.lineTo(x(point.x),y(point.y)+9);ctx.strokeStyle="#352449";ctx.lineWidth=1;ctx.stroke();
