+      <p className="island-insight">{transfer.reasons[active.transfer_answer.correct_reason]}</p>
+      <div className="island-action-pair"><button className="button secondary" disabled={isLocked} onClick={() => { apply(transfer.target_parameters, transfer.row ?? transfer.selected); onLocate(transfer.focus); }}><Eye size={20} />在画布看结果</button>
