function Stop-Owned($Process) {
    if (!$Process) { return }
    $all = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue)
    $ids = [System.Collections.Generic.List[int]]::new()
    $ids.Add($Process.Id)
