from pathlib import Path
import json,re,subprocess,sys
sys.path.insert(0,'scripts')
from privacy import has_local_identifier
files=set(subprocess.check_output(['git','ls-files','--cached','--others','--exclude-standard'],text=True,encoding='utf-8').splitlines())
issues=[]
for name in files:
 try:s=Path(name).read_text(encoding='utf-8-sig')
 except (UnicodeError,OSError):continue
 if has_local_identifier(s) or re.search(r'sk-[A-Za-z0-9_-]{12,}',s) or re.search(r'data:image/[^;\s]+;base64,[A-Za-z0-9+/=]{100}',s) or re.search(r'https?://[^\s"<>\\)]+[?&](?:sig|access_token|token)=[^\s"<>\\)]+',s):issues.append(name)
for line in Path('docs/ai-process/tool-events.jsonl').read_text(encoding='utf-8').splitlines():json.loads(line)
print(json.dumps({'checked_files':len(files),'privacy_issues':issues,'tool_jsonl':'valid'},ensure_ascii=False))
if issues:raise SystemExit(1)
